// StudentApplications.jsx — Updated to match class diagram
import { useState } from "react";
import StudentLayout from "../StudentLayout";

const GlobalStyles = () => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Syne:wght@400;600;700;800&family=DM+Sans:opsz,wght@9..40,300;9..40,400;9..40,500&display=swap');
    *, *::before, *::after { box-sizing:border-box; }
    body { font-family:'DM Sans',sans-serif; margin:0; background:#F7F9FC; }
    .font-syne { font-family:'Syne',sans-serif; }

    @keyframes fade-up { from{opacity:0;transform:translateY(14px)} to{opacity:1;transform:translateY(0)} }
    @keyframes shimmer { 0%{background-position:-200% center} 100%{background-position:200% center} }
    @keyframes spin    { to{transform:rotate(360deg)} }
    @keyframes scale-in{ from{opacity:0;transform:scale(.94)} to{opacity:1;transform:scale(1)} }
    @keyframes slide-up{ from{opacity:0;transform:translateY(20px)} to{opacity:1;transform:translateY(0)} }

    .anim-fade-up  { animation:fade-up .5s ease both; }
    .anim-d1 { animation-delay:.07s; }
    .anim-d2 { animation-delay:.14s; }
    .anim-d3 { animation-delay:.21s; }
    .anim-scale-in { animation:scale-in .3s ease both; }

    .shimmer-btn {
      background:linear-gradient(90deg,#1A4A8A 0%,#2E7DF7 45%,#1A4A8A 100%);
      background-size:200% auto; animation:shimmer 3s linear infinite;
    }
    .shimmer-btn:hover { box-shadow:0 6px 20px rgba(46,125,247,.35); }
    .shimmer-btn:disabled { opacity:.5; cursor:not-allowed; animation:none; background:#94A3B8; }

    .card { background:#fff; border-radius:16px; border:1px solid #E8EDF5; }

    .badge { display:inline-flex; align-items:center; font-size:.7rem; font-weight:600; padding:.25rem .65rem; border-radius:100px; }
    .badge-blue   { background:#EBF2FF; color:#2563EB; }
    .badge-green  { background:#ECFDF5; color:#059669; }
    .badge-orange { background:#FFF7ED; color:#D97706; }
    .badge-red    { background:#FEF2F2; color:#DC2626; }
    .badge-slate  { background:#F1F5F9; color:#475569; }
    .badge-purple { background:#F5F3FF; color:#7C3AED; }

    .skill-chip { display:inline-flex; align-items:center; font-size:.72rem; font-weight:500; padding:.3rem .75rem; border-radius:100px; background:#F1F5F9; color:#475569; border:1.5px solid #E2E8F0; }

    .tab-btn {
      padding:.5rem 1rem; border-radius:8px; font-size:.83rem; font-weight:500;
      cursor:pointer; transition:all .18s; border:none; background:transparent;
      font-family:'DM Sans',sans-serif;
    }
    .tab-btn.active   { background:#fff; color:#0B1F3A; box-shadow:0 1px 4px rgba(0,0,0,.1); }
    .tab-btn.inactive { color:#64748B; }
    .tab-btn.inactive:hover { color:#1C2B40; background:#F8FAFC; }

    .app-card { transition:all .2s ease; cursor:pointer; }
    .app-card:hover { transform:translateY(-2px); box-shadow:0 6px 20px rgba(11,31,58,.08); }
    .app-card.selected { border-color:#2E7DF7 !important; background:#F8FBFF; }

    .modal-overlay {
      position:fixed; inset:0; background:rgba(15,23,42,.55);
      backdrop-filter:blur(4px); z-index:50;
      display:flex; align-items:center; justify-content:center; padding:1rem;
    }
    .modal-box {
      background:#fff; border-radius:20px; width:100%; max-width:480px;
      padding:1.75rem; animation:slide-up .3s ease both;
      box-shadow:0 24px 64px rgba(0,0,0,.15);
    }
  `}</style>
);

const STATUS_MAP = {
  pending:  { label:"Pending",  badge:"badge-orange", dot:"bg-amber-400",  icon:"⏳", msg:"Awaiting company decision." },
  accepted: { label:"Accepted", badge:"badge-green",  dot:"bg-emerald-400",icon:"✅", msg:"Your application was accepted! Agreement being prepared." },
  rejected: { label:"Rejected", badge:"badge-red",    dot:"bg-red-400",    icon:"❌", msg:"Your application was not selected this time." },
};

const AGREEMENTS = {
  2: { startDate:"May 05, 2025", endDate:"Sep 05, 2025", validated: true,  ref:"AGR-2025-0042" },
};
const APPLICATIONS = [
  {
    id:1, company:"Sonatrach Digital", logo:"🛢️", role:"Full-Stack Developer",
    wilaya:"Alger", type:"On-site", duration:"6 months",
    appliedDate:"Apr 20, 2025",
    status:"pending",
    skills:["React","Node.js","PostgreSQL"],
    timeline:[
      {label:"Applied",             date:"Apr 20",  done:true  },
      {label:"Profile reviewed",    date:"Apr 22",  done:true  },
      {label:"Company decision",    date:"—",        done:false },
      {label:"Admin validation",    date:"—",        done:false },
      {label:"Agreement generated", date:"—",        done:false },
    ],
  },
  {
    id:2, company:"Ooredoo Labs", logo:"🌐", role:"Data Analyst",
    wilaya:"Alger", type:"Hybrid", duration:"4 months",
    appliedDate:"Apr 12, 2025",
    status:"accepted",
    skills:["Python","SQL","Power BI"],
    timeline:[
      {label:"Applied",             date:"Apr 12",  done:true },
      {label:"Profile reviewed",    date:"Apr 14",  done:true },
      {label:"Company decision",    date:"Apr 17",  done:true },
      {label:"Admin validation",    date:"Apr 19",  done:true },
      {label:"Agreement generated", date:"Apr 20",  done:true },
    ],
  },
  {
    id:3, company:"BNA Digital", logo:"🏦", role:"Backend Intern",
    wilaya:"Alger", type:"On-site", duration:"3 months",
    appliedDate:"Apr 5, 2025",
    status:"rejected",
    skills:["Java","Spring Boot","SQL"],
    timeline:[
      {label:"Applied",             date:"Apr 5",   done:true  },
      {label:"Profile reviewed",    date:"Apr 7",   done:true  },
      {label:"Company decision",    date:"Apr 10",  done:true  },
      {label:"Admin validation",    date:"—",        done:false },
      {label:"Agreement generated", date:"—",        done:false },
    ],
  },
];

const TABS = ["All","Pending","Accepted","Rejected"];

function Timeline({ steps, status }) {
  return (
    <div>
      {steps.map((step, i) => {
        const isLast    = i === steps.length - 1;
        const isRefused = status === "rejected" && i === 2 && step.done;
        const isDone    = step.done && !isRefused;
        return (
          <div key={i} className="flex gap-3">
            <div className="flex flex-col items-center">
              <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold border-2 shrink-0 transition-all ${
                isRefused ? "bg-red-100 border-red-400 text-red-600"
                : isDone  ? "bg-blue-500 border-blue-500 text-white"
                :           "bg-white border-slate-200 text-slate-300"
              }`}>
                {isRefused ? "✕" : isDone ? "✓" : String(i+1)}
              </div>
              {!isLast && (
                <div className={`w-0.5 h-8 mt-1 rounded-full transition-all ${isDone && !isRefused ? "bg-blue-200" : "bg-slate-100"}`}/>
              )}
            </div>
            <div className="pb-4 flex-1 min-w-0">
              <div className={`text-sm font-semibold ${isRefused?"text-red-600":isDone?"text-slate-800":"text-slate-400"}`}>
                {step.label}
              </div>
              <div className="text-xs text-slate-400 mt-0.5">{step.date}</div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function AgreementModal({ app, agreement, onClose }) {
  const [generating, setGenerating] = useState(false);
  const [generated,  setGenerated]  = useState(false);

  const generate = () => {
    setGenerating(true);
    setTimeout(()=>{ setGenerating(false); setGenerated(true); }, 1800);
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-box" onClick={e=>e.stopPropagation()}>
        {!generated ? (
          <>
            <div className="flex items-center gap-3 mb-5">
              <div className="w-12 h-12 bg-emerald-100 rounded-xl flex items-center justify-center text-2xl shrink-0">📜</div>
              <div>
                <h3 className="font-syne font-bold text-slate-900 text-lg">Convention de Stage</h3>
                <p className="text-xs text-slate-400">InternshipAgreement.generatePDF()</p>
              </div>
            </div>

            <div className="bg-slate-50 rounded-xl p-4 mb-5 space-y-2.5">
              <div className="flex justify-between text-sm"><span className="text-slate-500">Company</span><span className="font-semibold text-slate-800">{app.company}</span></div>
              <div className="flex justify-between text-sm"><span className="text-slate-500">Role</span><span className="font-semibold text-slate-800">{app.role}</span></div>
              <div className="flex justify-between text-sm"><span className="text-slate-500">Start date</span><span className="font-semibold text-slate-800">{agreement.startDate}</span></div>
              <div className="flex justify-between text-sm"><span className="text-slate-500">End date</span><span className="font-semibold text-slate-800">{agreement.endDate}</span></div>
              <div className="flex justify-between text-sm">
                <span className="text-slate-500">Admin validated</span>
                <span className={`font-semibold ${agreement.validated?"text-emerald-600":"text-amber-600"}`}>{agreement.validated ? "✓ Yes" : "⏳ Pending"}</span>
              </div>
            </div>

            {agreement.validated && (
              <button onClick={generate} disabled={generating} className="shimmer-btn w-full text-white font-semibold py-3 rounded-xl text-sm flex items-center justify-center gap-2">
                {generating ? <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"/> : "📄 Download Convention de Stage"}
              </button>
            )}

            <button onClick={onClose} className="w-full mt-3 text-sm text-slate-500 hover:text-slate-700 py-2 transition-colors">Close</button>
          </>
        ) : (
          <div className="text-center py-4 anim-scale-in">
            <div className="text-5xl mb-4">📄</div>
            <h3 className="font-syne font-bold text-slate-900 text-xl mb-2">PDF Generated!</h3>
            <button onClick={onClose} className="shimmer-btn w-full text-white font-semibold py-2.5 rounded-xl text-sm mt-4">Done</button>
          </div>
        )}
      </div>
    </div>
  );
}

export default function StudentApplications() {
  const [tab,      setTab]      = useState("All");
  const [selected, setSelected] = useState(APPLICATIONS[1]);
  const [modal,    setModal]    = useState(false);

  const filtered = tab === "All" ? APPLICATIONS : APPLICATIONS.filter(a => STATUS_MAP[a.status].label === tab);
  const agreement = selected ? AGREEMENTS[selected.id] : null;

  return (
    <>
      <GlobalStyles/>
      <StudentLayout active="applications">
        <div className="p-5 md:p-8">
          <div className="anim-fade-up mb-6">
            <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl">My applications</h1>
            <p className="text-slate-400 text-sm mt-0.5">{APPLICATIONS.length} total applications tracked</p>
          </div>

          <div className="anim-fade-up anim-d1 flex gap-1 bg-slate-100 rounded-xl p-1 w-fit mb-5">
            {TABS.map(t=>(
              <button key={t} onClick={()=>setTab(t)} className={`tab-btn ${tab===t?"active":"inactive"}`}>{t}</button>
            ))}
          </div>

          <div className="grid md:grid-cols-5 gap-5">
            <div className="md:col-span-2 anim-fade-up anim-d2 space-y-3">
              {filtered.map(app => {
                const s = STATUS_MAP[app.status];
                return (
                  <div key={app.id} onClick={()=>setSelected(app)} className={`card border app-card p-4 ${selected?.id===app.id?"selected":"border-slate-200"}`}>
                    <div className="flex items-start gap-3 mb-2.5">
                      <div className="w-10 h-10 rounded-xl bg-slate-100 flex items-center justify-center text-lg shrink-0">{app.logo}</div>
                      <div className="flex-1 min-w-0">
                        <h3 className="font-syne font-bold text-slate-800 text-sm truncate">{app.role}</h3>
                        <p className="text-xs text-slate-400">{app.company}</p>
                      </div>
                      <span className={`badge ${s.badge}`}>{s.label}</span>
                    </div>
                    <div className="flex justify-between items-center text-xs text-slate-400">
                      <span>Applied {app.appliedDate}</span>
                      <span className="flex items-center gap-1"><span className={`w-1.5 h-1.5 rounded-full ${s.dot}`}/>{app.type}</span>
                    </div>
                  </div>
                );
              })}
            </div>

            <div className="md:col-span-3 anim-fade-up anim-d3">
              {selected ? (
                <div className="card border border-slate-200 p-5 sticky top-4">
                  <div className="flex items-start gap-4 mb-5 pb-5 border-b border-slate-100">
                    <div className="w-14 h-14 rounded-2xl bg-slate-100 flex items-center justify-center text-3xl shrink-0">{selected.logo}</div>
                    <div className="flex-1">
                      <h2 className="font-syne font-extrabold text-slate-900 text-xl">{selected.role}</h2>
                      <p className="text-slate-500 text-sm">{selected.company}</p>
                    </div>
                  </div>

                  <div className={`rounded-xl p-3 mb-5 flex items-center gap-2 text-sm font-medium ${selected.status==="accepted" ? "bg-emerald-50 text-emerald-700 border border-emerald-200" : selected.status==="rejected" ? "bg-red-50 text-red-700 border border-red-200" : "bg-amber-50 text-amber-700 border border-amber-200"}`}>
                    <span>{STATUS_MAP[selected.status].icon}</span>{STATUS_MAP[selected.status].msg}
                  </div>

                  <div className="mb-4">
                    <h4 className="text-xs font-semibold text-slate-400 uppercase mb-4">Timeline</h4>
                    <Timeline steps={selected.timeline} status={selected.status}/>
                  </div>

                  {selected.status === "accepted" && agreement && (
                    <div className="pt-4 border-t border-slate-100">
                      <button onClick={()=>setModal(true)} disabled={!agreement.validated} className="shimmer-btn w-full text-white font-semibold py-3 rounded-xl text-sm">
                        📄 Download Convention de Stage
                      </button>
                    </div>
                  )}
                </div>
              ) : (
                <div className="card border border-slate-200 p-10 text-center text-slate-400">Select an application</div>
              )}
            </div>
          </div>
        </div>

        {modal && selected && agreement && (
          <AgreementModal app={selected} agreement={agreement} onClose={()=>setModal(false)}/>
        )}
      </StudentLayout>
    </>
  );
}
